CREATE DATABASE IF NOT EXISTS interior_design CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE interior_design;
CREATE TABLE IF NOT EXISTS design_projects(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(160) NOT NULL,style VARCHAR(80) NOT NULL,description TEXT NULL,image_url VARCHAR(500) NULL,is_published TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS consultation_requests(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,customer_name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL,phone VARCHAR(20) NULL,message VARCHAR(2000) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);